package org.dextur.reputation.probe;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.dextur.reputation.api.*;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;

/** Actual Paper service, native moving client, real command/GUI handlers, full PAPI and durable storage. */
final class RecoveryRuntimeProbe {
    private final JavaPlugin plugin;private final RecoveryService service;private Player target;private final List<RecoveryService.Changed> events=new CopyOnWriteArrayList<>();private RecoveryService.ProviderHandle provider;private final Path calendarDirectory,calendarConfiguration;private final org.dextur.reputation.application.ReputationApplication application;
    RecoveryRuntimeProbe(JavaPlugin plugin){this.plugin=plugin;calendarDirectory=plugin.getDataFolder().toPath().resolve("calendar-qa");calendarConfiguration=plugin.getServer().getPluginManager().getPlugin("DexturReputation").getDataFolder().toPath();application=(org.dextur.reputation.application.ReputationApplication)plugin.getServer().getServicesManager().load(ReputationService.class);service=plugin.getServer().getServicesManager().load(RecoveryService.class);}
    void start(Runnable success,Consumer<Throwable> failed){
        Path marker=plugin.getDataFolder().toPath().resolve("recovery-restart.txt");boolean restarted=Files.exists(marker),disabled=Boolean.getBoolean("dextur.probe.recovery-disabled");
        AutoCloseable listener=service.onChanged(events::add);
        poll(()->main(()->{target=plugin.getServer().getPlayerExact("Phase5Target");return target!=null;}),Boolean::booleanValue,0)
        .thenCompose(ignored->main(()->{target.setGameMode(GameMode.CREATIVE);target.setAllowFlight(true);target.setFlying(true);target.teleport(new Location(target.getWorld(),0,200,0));target.performCommand("rep language en_US");return true;}))
        .thenCompose(ignored->poll(()->main(()->application.cachedLanguage(target.getUniqueId())==org.dextur.reputation.domain.PlayerLanguage.en_US),Boolean::booleanValue,0))
        .thenCompose(ignored->service.status(target.getUniqueId()))
        .thenCompose(snapshot->{
            if(disabled){check(!snapshot.eligible()&&snapshot.reason().equals("DISABLED"),"Disabled eligibility");return service.start(target.getUniqueId()).handle((value,error)->{check(error!=null,"Disabled recovery enrolled");return snapshot;});}
            if(restarted){check(snapshot.status()==RecoverySnapshot.Status.COMPLETED,"Completed enrollment lost on restart");check(snapshot.rewards().size()==3,"Reward count lost on restart");return CompletableFuture.completedFuture(snapshot);}
            check(snapshot.eligible(),"Seeded player should be eligible: "+snapshot.reason());
            return main(()->{var denied=target.addAttachment(plugin,"dexturreputation.recovery.start",false);target.performCommand("rep recovery start");denied.remove();target.performCommand("rep recovery");return true;})
            .thenCompose(ignored->poll(()->main(()->{var inventory=target.getOpenInventory().getTopInventory();return inventory.getHolder()!=null&&inventory.getHolder().getClass().getName().endsWith("RecoveryGui$Session");}),Boolean::booleanValue,0))
            .thenCompose(ignored->service.status(target.getUniqueId())).thenCompose(before->{check(before.status()==RecoverySnapshot.Status.AVAILABLE,"Permission denial allowed enrollment");return main(()->{target.closeInventory();target.performCommand("rep recovery start");plugin.getServer().getPlayerExact("Phase5Other").performCommand("rep recovery start");return true;});})
            .thenCompose(ignored->poll(()->service.status(target.getUniqueId()),s->s.status()==RecoverySnapshot.Status.PAUSED&&s.stageId().equals("restoration"),0))
            .thenCompose(paused->{check(paused.rewards().size()==2,"Native activity/connected time did not grant two stages");check(paused.objectives().stream().anyMatch(o->o.type().equals("EXTERNAL")&&!o.available()),"Unavailable provider auto-completed");check(events.stream().anyMatch(e->e.kind()==RecoveryService.Kind.PROGRAM_PAUSED),"Missing committed pause event");
                provider=service.registerProvider(new RecoveryService.ObjectiveProvider(){public String id(){return "runtime-qa";}public int modelVersion(){return 1;}public boolean available(){return true;}public void validate(String id,Map<String,String> configuration){check(id.equals("restoration_active"),"Wrong provider objective");}});
                return main(()->{plugin.getServer().getPluginCommand("rep").execute(plugin.getServer().getConsoleSender(),"rep",new String[]{"admin","recovery",target.getName(),"resume","QA verified provider"});return paused;});})
            .thenCompose(paused->poll(()->service.status(target.getUniqueId()),s->s.status()==RecoverySnapshot.Status.ACTIVE,0))
            .thenCompose(active->{UUID operation=UUID.randomUUID(),enrollment=UUID.fromString(active.enrollmentId());var first=provider.submit(operation,target.getUniqueId(),enrollment,"restoration_active",1);var duplicate=provider.submit(operation,target.getUniqueId(),enrollment,"restoration_active",1);return first.thenCombine(duplicate,(a,b)->{check(a.rewards().size()==b.rewards().size(),"Concurrent duplicate callback changed rewards");return a;});})
            .thenCompose(ignored->poll(()->service.status(target.getUniqueId()),s->s.status()==RecoverySnapshot.Status.COMPLETED,0));
        }).thenCompose(snapshot->main(()->{target.performCommand("rep recovery status");target.performCommand("rep recovery tasks");target.performCommand("rep recovery rewards");target.performCommand("rep recovery");return snapshot;}))
        .thenCompose(snapshot->poll(()->main(()->{var inventory=target.getOpenInventory().getTopInventory();var item=inventory.getItem(40);return inventory.getHolder()!=null&&inventory.getHolder().getClass().getName().endsWith("RecoveryGui$Session")&&item!=null;}),Boolean::booleanValue,0).thenApply(ignored->snapshot))
        .thenCompose(snapshot->main(()->{var title=plain(target.getOpenInventory().title());check(title.equals("Reputation rehabilitation"),"English recovery title: "+title);target.closeInventory();target.performCommand("rep language ru_RU");return snapshot;}))
        .thenCompose(snapshot->poll(()->main(()->{target.performCommand("rep recovery");return plain(target.getOpenInventory().title()).equals("Восстановление репутации");}),Boolean::booleanValue,0).thenApply(ignored->snapshot))
        .thenCompose(snapshot->service.status(target.getUniqueId()))
        .thenCompose(snapshot->{if(disabled)return CompletableFuture.completedFuture(snapshot);check(snapshot.rewards().size()==3&&snapshot.rewards().stream().mapToLong(RecoverySnapshot.Reward::reputation).sum()==30,"Wrong bounded rewards");check(snapshot.completedTasks()==snapshot.objectives().size(),"Completed markers lost after provider shutdown/restart");return plugin.getServer().getServicesManager().load(VotingService.class).view(target.getUniqueId()).thenApply(view->{check(view.profile().communityScore()==-101&&view.profile().systemScore()==30&&view.profile().visibleScore()==-71,"Recovery changed community votes or split score");check(view.profile().tier().equals("SUSPICIOUS"),"Normal tier reconciliation missing");check(view.statistics().historyEntries()==0,"Fake votes created");return snapshot;});})
        .thenCompose(snapshot->disabled?CompletableFuture.completedFuture(snapshot):trust().thenApply(trust->{try{var explanation=(Map<?,?>)trust.getClass().getMethod("explanation").invoke(trust);check(Objects.equals(explanation.get("rehabilitation_credit"),10000L),"Bounded Trust credit missing");return snapshot;}catch(ReflectiveOperationException e){throw new CompletionException(e);}}))
        .thenCompose(snapshot->{if(disabled||restarted)return CompletableFuture.completedFuture(snapshot);return main(()->plugin.getServer().getPlayerExact("Phase5Other").getUniqueId()).thenCompose(id->service.status(id).thenCompose(other->{check(other.status()==RecoverySnapshot.Status.ACTIVE&&other.rewards().isEmpty()&&other.objectives().stream().filter(o->o.type().equals("ACTIVE_PLAYTIME")).allMatch(o->o.progress()==0),"AFK player earned active time");return service.cancel(id).thenCompose(cancelled->{check(cancelled.status()==RecoverySnapshot.Status.CANCELLED,"Cancel failed");return service.start(id).handle((value,error)->{check(error!=null,"Cancellation bypassed cooldown");return snapshot;});});}));})
        .thenCompose(snapshot->main(()->new org.dextur.reputation.domain.recovery.RecoveryData.Facts(target.isOnline()||target.hasPlayedBefore(),target.getStatistic(Statistic.PLAY_ONE_MINUTE)/20L,java.time.Instant.ofEpochMilli(target.getFirstPlayed())))).thenCompose(facts->application.submit(()->RecoveryCalendarRuntime.verify(calendarDirectory,calendarConfiguration,facts)))
        .thenCompose(ignored->service.status(target.getUniqueId()))
        .thenCompose(snapshot->main(()->{plugin.getLogger().info("PROBE_RECOVERY_CALENDAR_PASS: controlled authoritative dates, login-day deduplication, distinct dates, backend restart and WAIT downtime on isolated JSON QA storage");verifyPlaceholders(snapshot);if(!disabled){String rewards=snapshot.rewards().stream().map(r->r.operationId().toString()).collect(java.util.stream.Collectors.joining("\n"));if(restarted)check(Files.readString(marker).equals(rewards),"Restart duplicated reward IDs");else{Files.createDirectories(marker.getParent());Files.writeString(marker,rewards);}if(restarted)check(events.isEmpty(),"Restart replayed committed events");}return true;}))
        .whenComplete((ignored,error)->main(()->{try{listener.close();if(provider!=null)provider.close();if(error!=null){failed.accept(error);return null;}plugin.getLogger().info("PROBE_RECOVERY_PASS: "+(disabled?"disabled startup, rejection, GUI, locales and cache":"native active playtime, eligible login day, connected time, waiting, provider pause/resume, concurrent callback, bounded rewards, Trust, tiers, commands, GUI, locales and restart"));success.run();}catch(Throwable e){failed.accept(e);}return null;}));
    }
    private CompletionStage<Object> trust(){return main(()->{var reputation=plugin.getServer().getPluginManager().getPlugin("DexturReputation");var accessor=reputation.getClass().getDeclaredMethod("protectionAdministration");accessor.setAccessible(true);var admin=accessor.invoke(reputation);return (CompletionStage<?>)admin.getClass().getMethod("trust",UUID.class).invoke(admin,target.getUniqueId());}).thenCompose(stage->stage.thenApply(v->(Object)v));}
    private void verifyPlaceholders(RecoverySnapshot s)throws Exception{if(!plugin.getServer().getPluginManager().isPluginEnabled("PlaceholderAPI"))return;var papi=plugin.getServer().getPluginManager().getPlugin("PlaceholderAPI");var type=Class.forName("me.clip.placeholderapi.PlaceholderAPI",true,papi.getClass().getClassLoader());var method=type.getMethod("setPlaceholders",org.bukkit.OfflinePlayer.class,String.class);var expected=Map.of("status",s.status().name(),"stage",s.stageId(),"progress",Integer.toString(s.progressPercent()),"completed_tasks",Integer.toString(s.completedTasks()),"total_tasks",Integer.toString(s.objectives().size()),"eligible",Boolean.toString(s.eligible()));for(var entry:expected.entrySet())check(entry.getValue().equals(method.invoke(null,target,"%dexturreputation_recovery_"+entry.getKey()+"%")),"Recovery PAPI "+entry.getKey());plugin.getLogger().info("PROBE_RECOVERY_PAPI_PASS: all six values through full PlaceholderAPI parser");}
    private static String plain(Component c){return PlainTextComponentSerializer.plainText().serialize(c);}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    @FunctionalInterface private interface Checked<T>{T run()throws Exception;}
    private <T> CompletableFuture<T> main(Checked<T> task){var result=new CompletableFuture<T>();plugin.getServer().getScheduler().runTask(plugin,()->{try{result.complete(task.run());}catch(Throwable e){result.completeExceptionally(e);}});return result;}
    private <T> CompletionStage<T> poll(Supplier<CompletionStage<T>> action,Predicate<T> condition,int attempt){if(attempt>160)return CompletableFuture.failedFuture(new AssertionError("Recovery runtime condition timed out"));return action.get().thenCompose(value->{if(condition.test(value))return CompletableFuture.completedFuture(value);var next=new CompletableFuture<T>();plugin.getServer().getScheduler().runTaskLater(plugin,()->poll(action,condition,attempt+1).whenComplete((v,e)->{if(e==null)next.complete(v);else next.completeExceptionally(e);}),5L);return next;});}
}
